INSERT INTO ton_kho_odoo (seller_sku, free_qty, qty_available, cap_nhat_luc)
VALUES ($1, $2, $3, now())
ON CONFLICT (seller_sku) DO UPDATE SET free_qty = EXCLUDED.free_qty, qty_available = EXCLUDED.qty_available, cap_nhat_luc = now();
